/**
 * Table definitions shaped like the future Supabase (Postgres) schema.
 * Every table gets id, tenant_id, created_at, updated_at (see BASE_COLUMNS) — multi-tenant from day one.
 * supabase/schema.sql and docs/data-model.md are generated from here (npm run sql). Keep them in sync.
 */
import type { Bi } from '../specs/types';
import type { Tone } from '../design/tokens';
import type { IconName } from '../components/atom/Icon/Icon';

export type ColumnType = 'uuid' | 'text' | 'int' | 'numeric' | 'bool' | 'timestamptz' | 'date' | 'time' | 'json' | 'enum';

export interface ColumnDef {
  name: string;
  type: ColumnType;
  nullable?: boolean;
  /** Referenced table (column `id`). */
  references?: string;
  enum?: readonly string[];
  description?: string;
  /** Hide in default table view (long text, json). */
  wide?: boolean;
  /** 0044: the human name of the column in the table manager (M-03). Absent = the bilingual dictionary in src/data/labels.ts. */
  label?: Bi;
  /** 0044: a secret-adjacent value (a key hash): M-03 hides it from roles without tables.write. */
  sensitive?: boolean;
}

/**
 * 0044: what kind of thing a row is, so M-03 can pick a sensible default view and icon.
 * entity = a thing that exists (a person, a plan) · event = something that happens at a time (a booking, a payment) ·
 * link = a join between two things (a role grant, an RSVP) · config = a setting or a template · log = append-only history.
 */
export type TableKind = 'entity' | 'event' | 'link' | 'config' | 'log';

export type TableGroup = 'core' | 'people' | 'schedule' | 'analytics' | 'commerce' | 'comms' | 'manual' | 'system' | 'design';

export interface TableDef {
  name: string;
  label: Bi;
  description: Bi;
  group: TableGroup;
  /** 0044: see TableKind. */
  kind?: TableKind;
  /** 0044: the glyph beside the table in the M-03 sidebar and graph (the Icon atom's set). */
  icon?: IconName;
  columns: ColumnDef[];
  /** Column used as the human-readable title of a row. */
  titleColumn?: string;
  /** 0044: take the title from the row of another table that points here (users → the profiles row whose user_id is this user: the full name, not the email). */
  titleFrom?: { table: string; column: string };
  /** Per-table RLS intent, emitted as comments above the table in supabase/schema.sql and in docs/data-model.md. */
  rls?: string[];
}

export const BASE_COLUMNS: ColumnDef[] = [
  { name: 'id', type: 'uuid', description: 'Primary key' },
  { name: 'tenant_id', type: 'uuid', references: 'tenants', description: 'Owning studio (multi-tenant)' },
  { name: 'created_at', type: 'timestamptz' },
  { name: 'updated_at', type: 'timestamptz' },
];

export interface BaseRow {
  id: string;
  tenant_id: string;
  created_at: string;
  updated_at: string;
  [key: string]: unknown;
}

const money = (name: string, description?: string): ColumnDef => ({ name, type: 'int', description: description ?? 'COP, integer' });

