export const tableRegistry: Record<string, TableDef & { allColumns: ColumnDef[] }> = Object.fromEntries(
  tables.map((t) => [t.name, { ...t, allColumns: [...BASE_COLUMNS, ...t.columns] }]),
);

export const tableNames = tables.map((t) => t.name);
